import { Effect } from "effect"

type ReportFormat = "csv" | "json"

type ExportRequest = {
  readonly reportId: string
  readonly format: ReportFormat
  readonly includeHeaders: boolean
}

const resolveExportOptions = Effect.fn(function* (request: ExportRequest) {
  yield* Effect.logDebug("Resolving report export options")

  return {
    extension: request.format,
    contentType: request.format === "csv" ? "text/csv" : "application/json",
    headers: request.format === "csv" && request.includeHeaders
  }
})

export const prepareExport = Effect.fn(function* (request: ExportRequest) {
  const { extension, contentType, headers } = yield* resolveExportOptions(request)
  const filename = `${request.reportId}.${extension}`

  yield* Effect.logInfo(`Preparing export ${filename}`)

  return {
    filename,
    contentType,
    includeHeaders: headers,
    reportId: request.reportId
  }
})
